import {guides} from './guides.js';
// A guide's exact prefix protects strategic annotations from unrelated positions.
export function addKeyReasons(annotations){const entries=[
['london','Bf4','w','e3 전에 어두운 칸 비숍을 사슬 밖에 꺼내 중앙·왕측 활동을 확보합니다.','즉시 재료 위협보다 Ne5/e4 계획의 기반입니다.','흑은 …c5/…Qb6로 d4/b2를 압박해 백의 자동 배치를 시험할 수 있습니다.'],
['qgd','Bg5','w','d5를 지키는 f6 나이트를 퀸과의 핀으로 압박합니다.','중앙 수비 말의 자유를 제한하지만 당장 나이트가 공짜는 아닙니다.','흑은 …Be7로 핀을 완화하고 …c5/…e5 해방을 준비합니다.'],
['queens-gambit','Bg5','w','f6 나이트를 묶어 d5의 수비를 간접적으로 압박합니다.','기물 핀과 중앙 압력이 연결됩니다.','흑은 비숍 전개·중앙 돌파로 압박을 줄여야 합니다.'],
['qga','dxc4','b','d5를 직접 유지하는 대신 c4를 잡아 중앙 부담을 줄입니다.','백 c폰을 잡았고 잠시 여분 폰을 갖습니다.','백은 e3–Bxc4로 회복합니다. 흑이 폰만 지키면 전개와 퀸측 구조가 약해질 수 있습니다.'],
['tarrasch','c5','b','d4를 공격하며 흑 기물의 활동을 얻는 대신 교환 후 d5 고립폰 가능성을 감수합니다.','…cxd4로 중앙 구조를 바꿀 수 있습니다.','백은 교환 뒤 d4 봉쇄와 g2 비숍 압박을 준비할 수 있습니다.'],
['slav','c6','b','d5를 지키며 c8 비숍을 …e6 전에 꺼낼 선택을 남깁니다.','즉시 재료 위협보다 중앙 안정성이 목적입니다.','백은 e4 공간 또는 중앙 교환으로 이 구조를 시험합니다.'],
['semi-slav','b5','b','c4 비숍을 공격하며 퀸측 공간과 …Bb7–…c5 해방을 준비합니다.','…bxc4로 비숍을 잡을 수 있습니다.','백은 비숍을 옮긴 뒤 e4 중앙 확장을 준비합니다. 흑도 전개·…c5를 이어가야 합니다.'],
['french','c5','b','백 d4–e5 사슬의 밑부분 d4를 공격합니다.','…cxd4로 e5의 지지 기반을 없앨 수 있습니다.','백이 왕측 공격만 하면 중앙 수비가 무너질 수 있습니다.'],
['french-tarrasch','Nd2','w','e4를 지키며 …Bb4가 나이트를 킹에 핀하는 것을 피하고 c폰의 자유를 남깁니다.','직접 재료 위협은 없으며 c1 비숍의 길을 잠시 막는 비용이 있습니다.','흑은 …c5 또는 …Nf6로 중앙을 시험하므로 백은 구조에 맞춰 나이트 경로를 골라야 합니다.'],
['french-winawer','Bxc3+','b','어두운 칸 비숍을 나이트와 교환해 백 폰 구조 손상을 만들려 합니다.','체크이며 bxc3 후 c2/c3 더블폰이 생깁니다.','백은 비숍 쌍·열린 b열의 활동을 얻습니다. 흑은 구조 약점을 실제로 압박해야 교환의 의미가 있습니다.'],
['caro','dxe4','b','백 e4를 교환해 중앙 부담을 줄이고 비숍을 전개할 수 있는 구조를 만듭니다.','백 e폰을 잡아 중앙 구조가 바뀝니다.','백은 Nxe4로 활동을 얻습니다. 흑은 …Bf5와 …e6–…c5로 전개·해방을 연결합니다.'],
['caro-classical','Ng3','w','e4 나이트로 f5 비숍을 공격해 전개 템포를 얻습니다.','Nxf5로 비숍을 잡을 수 있습니다.','흑은 비숍 퇴로와 …h6를 준비합니다. 백도 가장자리 나이트의 다음 경로가 필요합니다.'],
['caro-exchange','Bd3','w','밝은 칸 비숍을 활동적으로 꺼내 h7을 보고 흑의 …Bf5 전개를 불편하게 합니다.','단독 메이트 위협보다 안정된 d4 구조의 활동이 목적입니다.','흑은 …Nc6/…Bg4와 중앙 …e5로 백의 공격 시간을 줄이려 합니다.'],
['sicilian-taimanov','Qc7','b','e5 칸·c열과 중앙 …d5 준비를 연결하고 기물 배치를 유연하게 남깁니다.','직접 강제 공격보다 중앙 돌파 지원입니다.','백 Nb5가 퀸과 d6/c7을 겨냥할 수 있어 …a6 타이밍을 확인합니다.'],
['sicilian-kan','a6','b','Nb5/Bb5를 막고 …b5–Bb7 확장과 유연한 나이트 배치를 준비합니다.','즉시 재료 위협은 없습니다.','전개를 너무 늦추면 백의 중앙·왕측 활동이 빨라집니다.'],
['sicilian-dragon','g6','b','g7 비숍의 긴 대각선으로 중앙·퀸측 반격을 준비합니다.','즉시 강제 공격은 아니며 왕측에 폰 공격의 갈고리도 생깁니다.','백은 Be3/Qd2/Bh6와 h폰 공격을 준비할 수 있어 중앙 …d5와 c열 반격을 연결해야 합니다.'],
['sicilian-accelerated','g6','b','…d6를 늦춰 중앙 …d5를 한 번에 두는 선택을 남기며 피안케토를 준비합니다.','…d5 해방 가능성은 실제 기물 배치에 따라 달라집니다.','백 c4가 d5를 추가 통제하면 마로치 바인드의 기동 계획이 필요합니다.'],
['grunfeld','Nxc3','b','중앙 나이트를 교환해 백 b폰을 c3로 유도하고 큰 폰 중앙을 공격할 목표로 만듭니다.','백 c3 나이트를 잡았습니다.','백은 bxc3로 d4 지지를 얻습니다. 흑은 …Bg7·…c5로 d4를 압박하지 않으면 공간만 내줍니다.'],
['kings-indian','e5','b','백 d4를 공격해 중앙 교환 또는 닫힌 사슬의 방향을 선택하게 합니다.','…exd4로 중앙을 교환할 수 있습니다.','백 d5면 흑 …f5/백 c5의 날개 계획, dxe5면 열린 중앙으로 계획이 달라집니다.'],
['benoni','exd5','b','e폰을 교환해 c5–d6와 백 d5–e4의 비대칭 폰 다수를 준비합니다.','백 d5폰을 잡았습니다.','cxd5 후 흑은 d6 부담을 …b5·g7 비숍 활동으로 보상해야 합니다.'],
['benko','b5','b','b폰을 희생해 a/b열과 퀸측 대각선의 장기 활동을 준비합니다.','…bxc4로 백 중앙 지지 폰을 제거할 수 있습니다.','백이 수락하면 여분 폰과 열린 열의 수비 부담을 함께 가집니다. 흑은 룩 활동을 이어가야 합니다.'],
['catalan','g3','w','g2 비숍의 긴 대각선 압력과 d4/c4 중앙을 결합합니다.','즉시 재료 위협보다 d5/c6/b7의 장기 압력입니다.','흑은 …dxc4로 폰을 잡거나 …c5로 중앙을 공격하므로 백은 전개·폰 회복을 조율합니다.'],
['queens-indian','Bb7','b','밝은 칸 비숍을 긴 대각선에 두어 f6 나이트와 e4를 통제합니다.','e4 중앙 확장을 견제합니다.','백은 g2 비숍·중앙 기물로 대각선을 다투며 흑 …d5 이후 자기 비숍이 막히는지도 확인해야 합니다.'],
['larsen','Bb2','w','어두운 칸 비숍으로 e5·왕측 긴 대각선을 압박합니다.','중앙 폰이 막고 있어 즉시 강제 공격은 아닙니다.','흑이 …d5–…e5로 공간을 얻으면 백은 c4/f4 등 중앙 돌파로 비숍을 살려야 합니다.'],
['stonewall','f4','w','d4와 함께 e5를 두 번 지지해 나이트 공격 거점을 준비합니다.','장기 e5 통제이며 e4·킹 대각선 수비가 줄어드는 비용이 있습니다.','흑은 …Ne4/…c5와 비숍 교환으로 백 왕측 공격을 줄이려 합니다.'],
['bird','f4','w','e5를 직접 통제하고 역 더치형의 왕측 공간을 준비합니다.','즉시 강제 위협은 없고 e1–h4 킹 대각선이 약해집니다.','흑의 …d5 공간과 1…e5 프롬 갬빗에 각각 다른 중앙 대응이 필요합니다.'],
['alapin','c3','w','d4 중앙을 폰으로 지지할 준비를 합니다.','다음 d4가 계획이며 나이트의 c3 전개를 막는 비용이 있습니다.','흑은 …d5/…Nf6로 즉시 중앙을 시험할 수 있습니다.'],
['smith-morra','c3','w','d4의 흑 폰에 c폰을 내주어 Nxc3를 전개 템포로 두려 합니다.','…dxc3를 허용하는 폰 희생입니다.','흑은 수락 뒤 …d5 해방을 준비하거나 거절해 다른 중앙 구조로 갈 수 있습니다.'],
['rossolimo','Bxc6','w','비숍 쌍을 내주는 대신 흑 c폰 구조를 손상시키고 중앙을 통제하려 합니다.','흑 c6 나이트를 잡았습니다.','…dxc6이면 더블 c폰·반열린 d열, …bxc6이면 다른 중앙 지지 구조가 되어 각각 평가해야 합니다.'],
['moscow','Bb5+','w','체크를 전개 수와 결합해 흑의 비숍·나이트 배치를 선택하게 합니다.','체크이므로 응수가 필요합니다.','…Bd7 교환형에는 더블폰이 없고 …Nd7/…Nc6에는 다른 말 배치가 생깁니다.'],
['grand-prix','f4','w','왕측 공간과 e5 통제를 늘려 비숍·나이트·퀸의 공격을 준비합니다.','즉시 강제 위협보다 f5 돌파의 기반입니다.','흑 …d5가 중앙을 열 수 있으므로 킹 안전 없이 측면 폰만 전진하지 않습니다.'],
['evans','b4','w','흑 c5 비숍을 유인해 c3를 비숍 공격 템포로 두고 d4를 준비합니다.','bxc5로 비숍을 잡을 수 있습니다.','흑이 폰을 수락하면 백은 빠르게 전개해야 하며 느린 수로 시간을 버리면 보상이 줄어듭니다.'],
['kings-gambit','f4','w','흑 e5 기반을 흔들고 f열을 열기 위해 킹 주변 폰을 희생합니다.','fxe5 가능성을 만들지만 e1–h4 대각선이 약해집니다.','흑 …exf4 뒤 전개·킹 안전·중앙 …d5를 먼저 계산합니다.'],
['marshall','d5','b','중앙 폰을 희생해 e열·비숍 대각선·중앙 나이트 활동을 얻습니다.','백 e4를 공격하고 중앙을 열려 합니다.','백이 폰을 잡으면 흑은 …Bd6·왕측 퀸·룩 압력을 정확한 수순으로 이어가야 합니다.'],
['budapest','e5','b','백 d4 중앙에 폰을 내주고 나이트의 e5 회복과 빠른 전개를 준비합니다.','…exd4로 중앙 폰을 잡을 수 있습니다.','백 dxe5 뒤 흑은 …Ng4/…Nc6로 폰을 공격하며 전개를 마쳐야 합니다.'],
['englund','e5','b','중앙 폰을 희생해 빠른 활동을 찾지만 보상이 충분한지 주의가 필요한 선택입니다.','…exd4로 중앙을 교환할 수 있습니다.','백 dxe5와 자연스러운 전개에 퀸만 반복 이동하면 폰 부족과 전개 지연이 함께 남습니다.'],
['latvian','f5','b','e4에 측면 반격을 시도하지만 왕측 대각선과 전개에 큰 비용을 냅니다.','…fxe4로 중앙 폰을 잡을 수 있습니다.','백 Nxe5·중앙 확장과 퀸 공격을 견딜 정확한 전개·킹 수비가 필요합니다.'],
];
for(const [id,san,color,why,threat,ignore] of entries){const seq=guides.find(g=>g.id===id).line.split(' ');const i=seq.findIndex((m,j)=>m===san&&(j%2?'b':'w')===color);if(i<0)throw Error('Key move missing: '+id);const line=seq.slice(0,i+1);if(!annotations.some(a=>a.line.join(' ')===line.join(' ')))annotations.push({line,why,threat,ignore});}
}
